#include "stdlib/complex/float64/base/sub.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/complex/float64/reim.h"

/**
* Subtracts two double-precision complex floating-point numbers.
*
* @param z1       input value
* @param z2       input value
* @return         result
*
* @example
* #include "stdlib/complex/float64/ctor.h"
* #include "stdlib/complex/float64/real.h"
* #include "stdlib/complex/float64/imag.h"
*
* stdlib_complex128_t z1 = stdlib_complex128( 5.0, 3.0 );
* stdlib_complex128_t z2 = stdlib_complex128( -2.0, 1.0 );
*
* stdlib_complex128_t out = stdlib_base_complex128_sub( z1, z2 );
*
* double re = stdlib_complex128_real( out );
* // returns 7.0
*
* double im = stdlib_complex128_imag( out );
* // returns 2.0
*/
stdlib_complex128_t stdlib_base_complex128_sub( const stdlib_complex128_t z1, const stdlib_complex128_t z2 ) {
	double re1;
	double re2;
	double im1;
	double im2;
	double re;
	double im;

	stdlib_complex128_reim( z1, &re1, &im1 );
	stdlib_complex128_reim( z2, &re2, &im2 );

	re = re1 - re2;
	im = im1 - im2;

	return stdlib_complex128( re, im );
}","lineStart":1,"lineEnd":61,"totalLines":61,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-base-sub/src/main.c","time":{"start":1783262347673,"end":1783262347680}},"id":"prt_f32b800e7001rkIxMdOkqiAX7U","sessionID":"ses_0cd48484fffebJjYluzJnl7c15","messageID":"msg_f32b7f9960011I78ufMeAZ8KBc"}}

